def clean(a):
    return {k: v for k, v in a.items() if v}

def derivative(a):
    return clean({k - 1: k * v for k, v in a.items()})

def add(a, b):
    out = dict(a)
    for k, v in b.items():
        out[k] = out.get(k, Q(0)) + v
    return clean(out)

def scale(a, c):
    return clean({k: c * v for k, v in a.items()})

def multiply(a, b):
    out = {}
    for i, x in a.items():
        for j, y in b.items():
            out[i + j] = out.get(i + j, Q(0)) + x * y
    return clean(out)

def value_at_zero(a):
