import json

n = 33146799

def factorize(num):
    factors = {}
    m = num
    d = 2
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

def is_prime(k):
    if k < 2:
        return False
    d = 2
    while d * d <= k:
        if k % d == 0:
            return False
        d += 1
    return True

factors = factorize(n)

product = 1
for p, e in factors.items():
    product *= p ** e

all_prime = all(is_prime(p) for p in factors)

if product != n or not all_prime or not factors:
    print("UNSUPPORTED")
