    "J": "spherical little ancient walking good indigo bangladeshi jar",
}

# Derive ordered category precedence from the given sentences (head noun = last word).
rel = set()
for s in SENTS:
    c = [CAT[w] for w in s.split()[:-1] if w in CAT]
    for i in range(len(c)):
        for j in range(i + 1, len(c)):
            if c[i] != c[j]:
                rel.add((c[i], c[j]))

# Transitive closure.
changed = True
while changed:
    changed = False
    for (a, b) in list(rel):
        for (c, d) in list(rel):
            if b == c and a != d and (a, d) not in rel:
                rel.add((a, d))
                changed = True

contradictions = sorted({(a, b) for (a, b) in rel if (b, a) in rel})

# Judge each option pairwise.
status, reasons = {}, {}
for k, s in OPTS.items():
