def check_brackets(s):
    # Match pairs
    mapping = {')': '(', '}': '{', ']': '[', '>': '<'}
    opening = set(mapping.values())

    # Process input tokens (ignoring whitespace)
    tokens = s.split()
    stack = []
    for t in tokens:
        if t in opening:
            stack.append(t)
        elif t in mapping:
            if not stack:
                return False, f"Unexpected closing bracket {t}"
            top = stack.pop()
            if top != mapping[t]:
                return False, f"Mismatched bracket: expected {top} closed, got {t}"
        else:
            return False, f"Unknown token {t}"

    return True, stack

input_seq = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
valid, remaining_stack = check_brackets(input_seq)

if not valid:
    print(f"Input is invalid: {remaining_stack}")
    print("CHECK FAIL")
else:
    # To close properly, each unclosed bracket must be closed in reverse order
    reverse_map = {'(': ')', '{': '}', '[': ']', '<': '>'}
    expected_closing = [reverse_map[b] for b in reversed(remaining_stack)]
    expected_full = input_seq + " " + " ".join(expected_closing)

    submitted = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ] ) ] ) ]"

    submitted_valid, submitted_stack = check_brackets(submitted)

    print(f"Remaining stack from input: {remaining_stack}")
    print(f"Expected closing tokens: {expected_closing}")
    print(f"Submitted is valid: {submitted_valid and len(submitted_stack) == 0}")

    if submitted.split() == expected_full.split():
        print("CHECK PASS")
    else:
        print(f"Expected full: {expected_full}")
        print(f"Submitted full: {submitted}")
        print("CHECK FAIL")
