import itertools
import json

# People and their languages:
# South Korea (K), France (F), Britain (B), Germany (G)
languages = {
    'K': {'Korean'},
    'F': {'French', 'German'},
    'B': {'English', 'Korean'},
    'G': {'Korean', 'French', 'English', 'German'}
}

def can_communicate(p1, p2):
    return len(languages[p1] & languages[p2]) > 0

nationalities = ['K', 'F', 'B', 'G']
valid_orders = []

for perm in itertools.permutations(nationalities):
    # perm[0] is room 1, perm[1] is room 2, perm[2] is room 3, perm[3] is room 4
    room = {person: i + 1 for i, person in enumerate(perm)}

    # Neighbors of a room
    def neighbors(person):
        r = room[person]
        res = []
        if r > 1:
            res.append(perm[r - 2])
        if r < 4:
            res.append(perm[r])
        return res

    # Condition 1: Korean room > German room
    if not (room['K'] > room['G']):
        continue

    # Condition 2: Korean cannot communicate with neighbors
    k_neighbors = neighbors('K')
    if any(can_communicate('K', n) for n in k_neighbors):
        continue

    # Condition 3: French cannot communicate with neighbors
    f_neighbors = neighbors('F')
    if any(can_communicate('F', n) for n in f_neighbors):
        continue

    # Condition 4: British can only communicate with one of their neighbors
    b_neighbors = neighbors('B')
    comm_count = sum(1 for n in b_neighbors if can_communicate('B', n))
    if comm_count != 1:
        continue

    valid_orders.append(perm)

name_map = {
    'K': 'South Korea',
    'F': 'France',
    'B': 'Britain',
    'G': 'Germany'
}

options = {
