    'B': ('France', 'Britain', 'Germany', 'South Korea'),
    'C': ('Germany', 'Britain', 'France', 'South Korea'),
    'D': ('Germany', 'Britain', 'South Korea', 'France')
}

selected_option = None
result_tuple = tuple(name_map[p] for p in valid_orders[0])

for opt, val in options.items():
    if val == result_tuple:
        selected_option = opt
        break

print(json.dumps({
    "final_answer": selected_option,
    "evidence": f"Order: {', '.join(result_tuple)}"
}))
