            if 0 <= t <= 1 and 0 <= u <= 1:
                p = (a[0] + t * r[0], a[1] + t * r[1])
                cuts[i].add(p)
                cuts[j].add(p)
        elif cross(q, r) == 0:
            for p in (a, b, c, d):
                if on_segment(p, a, b) and on_segment(p, c, d):
                    cuts[i].add(p)
                    cuts[j].add(p)

