    for i in range(n):
        for j in range(i + 1, n):
            if j == i + 1 or (i == 0 and j == n - 1):
                continue
            a, b = poly[i], poly[j]
            mid = ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
