            for p in (c, d):
                if on_segment(p, a, b):
                    cuts[i].append(max(0.0, min(1.0, param_on(p, a, b))))

coords = {}
edges = set()

def node(p):
    # Merge numerically equivalent intersection coordinates.
    key = (round(p[0], 4), round(p[1], 4))
    coords.setdefault(key, key)
    return key

for (a, b), ts in zip(segments, cuts):
    ts = sorted(ts)
    unique = []
    for t in ts:
        if not unique or abs(t - unique[-1]) > 1e-8:
            unique.append(t)
    d = sub(b, a)
    ns = [node((a[0] + t * d[0], a[1] + t * d[1])) for t in unique]
    for u, v in zip(ns, ns[1:]):
        if u != v:
            edges.add(tuple(sorted((u, v))))

adj = {v: set() for v in coords}
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Enumerate simple cycles of the split line graph.
cycles = set()
max_raw_vertices = 32
for start in sorted(adj):
    path = [start]
    used = {start}

    def walk(v):
        for w in adj[v]:
            if w == start:
                if len(path) >= 3:
                    cyc = tuple(path)
                    rev = (cyc[0],) + tuple(reversed(cyc[1:]))
                    cycles.add(min(cyc, rev))
                continue
            if w < start or w in used or len(path) >= max_raw_vertices:
                continue
            used.add(w)
            path.append(w)
            walk(w)
            path.pop()
            used.remove(w)

    walk(start)

def simplify(poly):
    p = list(poly)
    changed = True
    while changed and len(p) > 2:
        changed = False
        out = []
        n = len(p)
        for i in range(n):
            prev, cur, nxt = p[i - 1], p[i], p[(i + 1) % n]
            u, v = sub(cur, prev), sub(nxt, cur)
            scale = max(1.0, length(u) * length(v))
            if abs(cross(u, v)) <= 2e-4 * scale and dot(u, v) > 0:
                changed = True
            else:
                out.append(cur)
        p = out
    return p

def area2(p):
    return sum(cross(p[i], p[(i + 1) % len(p)]) for i in range(len(p)))

def parallel(u, v):
    return abs(cross(u, v)) <= 2e-3 * max(1.0, length(u) * length(v))

def perpendicular(u, v):
    return abs(dot(u, v)) <= 2e-3 * max(1.0, length(u) * length(v))

def convex(p):
    signs = []
    for i in range(len(p)):
        z = cross(sub(p[(i + 1) % len(p)], p[i]),
                  sub(p[(i + 2) % len(p)], p[(i + 1) % len(p)]))
        if abs(z) > 1e-7:
            signs.append(z > 0)
    return bool(signs) and all(s == signs[0] for s in signs)

def diagonal_drawn(a, b):
    chord = sub(b, a)
    L = length(chord)
    intervals = []
    for c, d in segments:
        if (abs(cross(sub(c, a), chord)) <= 1e-3 * L
                and abs(cross(sub(d, a), chord)) <= 1e-3 * L):
            lo, hi = sorted((dot(sub(c, a), chord) / (L * L),
                             dot(sub(d, a), chord) / (L * L)))
            lo, hi = max(0.0, lo), min(1.0, hi)
            if hi >= lo:
                intervals.append((lo, hi))
    intervals.sort()
    reach = 0.0
    for lo, hi in intervals:
        if lo > reach + 2e-4:
            return False
        reach = max(reach, hi)
        if reach >= 1 - 2e-4:
            return True
    return False

def has_diagonal(p):
    n = len(p)
    for i in range(n):
        for j in range(i + 1, n):
            if j == i + 1 or (i == 0 and j == n - 1):
                continue
            if diagonal_drawn(p[i], p[j]):
                return True
    return False

def classify(p):
    n = len(p)
    if n not in (3, 4, 5, 6) or abs(area2(p)) < 1e-7:
        return None
    isconv = convex(p)
    sides = [sub(p[(i + 1) % n], p[i]) for i in range(n)]
    lens = [length(v) for v in sides]

    if has_diagonal(p):
        return None

    if n == 3:
        right = any(perpendicular(sides[i], sides[(i + 1) % 3]) for i in range(3))
        return 4 if right else 3

    if n == 4 and isconv:
        pairs = [parallel(sides[0], sides[2]), parallel(sides[1], sides[3])]
        if all(pairs):
            rect = all(perpendicular(sides[i], sides[(i + 1) % 4]) for i in range(4))
            equal = max(lens) - min(lens) <= 2e-3 * max(lens)
            if rect:
                return 2 if equal else 1
            return 5
        if sum(pairs) == 1:
            return 6
        return None

    if n == 5:
        if isconv:
            regular = (max(lens) - min(lens) <= 2e-3 * max(lens)
                       and all(parallel(sides[i], (-sides[(i + 2) % 5][0],
                                                   -sides[(i + 2) % 5][1]))
                               for i in range(5)))
            return 9 if regular else 7
        return 8

    if n == 6 and isconv:
        regular = (max(lens) - min(lens) <= 2e-3 * max(lens)
                   and all(parallel(sides[i], (-sides[(i + 3) % 6][0],
                                               -sides[(i + 3) % 6][1]))
                           for i in range(3)))
        return 10 if regular else None
    return None

found = set()
accepted = 0
for cyc in cycles:
    p = simplify([coords[v] for v in cyc])
    if len(p) < 3:
        continue
    kind = classify(p)
    if kind is not None:
        found.add(kind)
        accepted += 1

choices = {
    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5},
    "E": {1, 5, 7, 8}, "F": {1, 5, 7, 8, 4, 6},
    "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2},
    "N": {1, 8, 2, 4, 9}, "O": {1, 5, 7, 8, 10},
    "P": {1, 7, 8, 6},
}
matches = [letter for letter, values in choices.items() if values == found]
answer = matches[0] if len(matches) == 1 else "UNSUPPORTED"
print(json.dumps({
    "final_answer": answer,
    "evidence": {"shape_numbers": sorted(found), "matching_options": matches,
                 "cycles_examined": len(cycles), "classified_cycles": accepted}
}, separators=(",", ":")))
