def drawn_chord(poly, i, j):
    """Check whether the straight segment between two nonadjacent corners
    is covered by drawn strokes and lies inside the polygon."""
    a, b = poly[i], poly[j]
    d = sub(b, a)
    dd = dot(d, d)
    if dd == 0:
        return False
    # A chord must actually be inside, not merely pass through the polygon.
    for k in range(1, 20):
        t = k / 20
        p = (a[0] + t * d[0], a[1] + t * d[1])
        if not point_inside(p, poly):
            return False

    intervals = []
    for c, e in segments:
        s = sub(e, c)
        if abs(cross(d, s)) > 1e-7 * max(1.0, norm(d) * norm(s)):
            continue
        if abs(cross(d, sub(c, a))) > 1e-7 * max(1.0, norm(d)):
            continue
        t0 = dot(sub(c, a), d) / dd
        t1 = dot(sub(e, a), d) / dd
        lo, hi = max(0.0, min(t0, t1)), min(1.0, max(t0, t1))
        if hi >= lo - 1e-8:
            intervals.append((lo, hi))
    intervals.sort()
    end = 0.0
    for lo, hi in intervals:
        if lo > end + 1e-7:
            return False
        end = max(end, hi)
    return end >= 1.0 - 1e-7


def has_diagonal(poly):
    n = len(poly)
    for i in range(n):
        for j in range(i + 1, n):
            if j == i + 1 or (i == 0 and j == n - 1):
                continue
            if drawn_chord(poly, i, j):
                return True
    return False


def parallel(a, b, c, d):
    u, v = sub(b, a), sub(d, c)
    return abs(cross(u, v)) <= 1e-6 * max(1.0, norm(u) * norm(v))


def is_right(poly):
    n = len(poly)
    for i in range(n):
        u = sub(poly[(i - 1) % n], poly[i])
        v = sub(poly[(i + 1) % n], poly[i])
        if abs(dot(u, v)) > 1e-5 * max(1.0, norm(u) * norm(v)):
            return False
    return True


def is_regular(poly):
    n = len(poly)
    lengths = [norm(sub(poly[(i + 1) % n], poly[i])) for i in range(n)]
    if max(lengths) - min(lengths) > 1e-4 * max(lengths):
        return False
    # Equal side lengths alone are insufficient: require equal interior angles.
    cosines = []
    for i in range(n):
        u = sub(poly[(i - 1) % n], poly[i])
        v = sub(poly[(i + 1) % n], poly[i])
        cosines.append(dot(u, v) / (norm(u) * norm(v)))
    return max(cosines) - min(cosines) <= 1e-5


found = set()
witnesses = {i: [] for i in range(1, 11)}
seen_polygons = set()

for cyc in cycles:
    raw = [coords[i] for i in cyc]
    poly = simplify(raw)
    n = len(poly)
    if n < 3 or abs(area2(poly)) < 1e-8:
        continue

    # Canonicalize the simplified polygon to avoid counting it more than once.
    rounded = tuple(vertex_key(p) for p in poly)
    rev = tuple(reversed(rounded))
    forms = []
    for seq in (rounded, rev):
        forms.extend(seq[k:] + seq[:k] for k in range(n))
    key = min(forms)
    if key in seen_polygons:
        continue
    seen_polygons.add(key)

    # Determine convexity from the signed turns.
    turns = []
    for i in range(n):
        turns.append(cross(sub(poly[(i + 1) % n], poly[i]),
                           sub(poly[(i + 2) % n], poly[(i + 1) % n])))
    convex = all(t >= -1e-7 for t in turns) or all(t <= 1e-7 for t in turns)
    if has_diagonal(poly):
        continue

    category = None
    if n == 3:
        category = 4 if is_right(poly) else 3
    elif n == 4:
        p0, p1, p2, p3 = poly
        pairs = (parallel(p0, p1, p2, p3),
                 parallel(p1, p2, p3, p0))
        if all(pairs):
            if is_right(poly):
                lengths = [norm(sub(poly[(i + 1) % 4], poly[i]))
                           for i in range(4)]
                category = 2 if max(lengths) - min(lengths) <= 1e-5 else 1
            else:
                category = 5
        elif sum(pairs) == 1:
            category = 6
    elif n == 5:
        if convex:
            category = 9 if is_regular(poly) else 7
        else:
            category = 8
    elif n == 6 and convex and is_regular(poly):
        category = 10

    if category is not None:
        found.add(category)
        if len(witnesses[category]) < 2:
            witnesses[category].append(poly)


options = {
    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5},
    "E": {1, 5, 7, 8}, "F": {1, 5, 7, 8, 4, 6},
    "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2},
    "N": {1, 8, 2, 4, 9}, "O": {1, 5, 7, 8, 10},
    "P": {1, 7, 8, 6},
}
claimed = "E"

print("Parsed line segments:", len(segments))
print("Enumerated simple cycles:", len(cycles))
print("Detected shape numbers:", sorted(found))
for number in sorted(found):
    print("Shape", number, "witness:", witnesses[number][0])
print("Claimed option", claimed, "contains:", sorted(options[claimed]))
print("CHECK PASS" if found == options[claimed] else "CHECK FAIL")
