import json

sequence = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
matching = {")": "(", "}": "{", ">": "<", "]": "["}
closing = {"(": ")", "{": "}", "<": ">", "[": "]"}
stack = []
supported = True

for char in sequence:
    if char.isspace():
        continue
    if char in closing:
        stack.append(char)
    elif char in matching:
        if not stack or stack[-1] != matching[char]:
            supported = False
            break
        stack.pop()
    else:
        supported = False
        break

if not supported:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": "Invalid or mismatched delimiter sequence."}))
else:
    suffix = "".join(closing[opener] for opener in reversed(stack))
    result = sequence + suffix
    print(json.dumps({
        "final_answer": result,
        "evidence": {"appended_closers": suffix, "unclosed_openers": "".join(stack)}
    }, separators=(",", ":")))
