nationalities = ("South Korea", "France", "Britain", "Germany")
languages = {"Korean", "French", "English", "German"}

# Each person speaks their country's language, plus any additional languages
# explicitly stated in the problem.
speaks = {
    "South Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"English", "Korean"},
    "Germany": set(languages),
}

def can_communicate(a, b):
    return bool(speaks[a] & speaks[b])

valid = []
for rooms in itertools.permutations(nationalities):
    room_of = {person: i + 1 for i, person in enumerate(rooms)}

    def neighbors(person):
        i = room_of[person] - 1
        return [rooms[j] for j in (i - 1, i + 1) if 0 <= j < 4]

    if room_of["South Korea"] <= room_of["Germany"]:
        continue
    if any(can_communicate("South Korea", n) for n in neighbors("South Korea")):
        continue
    if "German" not in speaks["France"]:
        continue
    if any(can_communicate("France", n) for n in neighbors("France")):
        continue
    if "Korean" not in speaks["Britain"]:
        continue
    if sum(can_communicate("Britain", n) for n in neighbors("Britain")) != 1:
        continue
    if speaks["Germany"] != languages:
        continue

    valid.append(rooms)

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
