# Match each coefficient of t to zero and solve the resulting equations for b.
equations = {}
for (t_power, b_power, c_power), coefficient in difference.items():
    assert c_power == 0
    equation = equations.setdefault(t_power, {})
    equation[b_power] = equation.get(b_power, Fraction(0)) + coefficient

b_value = None
for equation in equations.values():
    if equation.get(1, 0):
        b_value = -equation.get(0, Fraction(0)) / equation[1]
        break
assert b_value is not None
assert all(
    sum(coefficient * b_value**power for power, coefficient in equation.items()) == 0
    for equation in equations.values()
)

# Each value is represented as (coefficient of c, constant term).
values = {}
for x, label in [(1, "f(1)"), (2, "f(2)"), (4, "f(4)")]:
    values[label] = (Fraction(1), Fraction(x * x) + b_value * x)

assert len({constant for _, constant in values.values()}) == len(values)
ordered = sorted(values, key=lambda label: values[label][1])
answer = ", ".join(ordered)

def format_value(value):
    c_coefficient, constant = value
    if c_coefficient == 1:
        return "c" if constant == 0 else f"c{constant:+}"
    return str(c_coefficient) + "c" + (f"{constant:+}" if constant else "")

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "b": str(b_value),
        "values": {label: format_value(value) for label, value in values.items()},
        "increasing_constants": [str(values[label][1]) for label in ordered]
    }
}))
