import itertools
import json
import math

# Sort any solution as a <= b <= c and put k = a^2 b^2.
# From c^3 <= a^3+b^3+c^3 = k c^2, we get c <= k.
# Also, a^3+b^3+c^3 <= 3c^3, so k <= 3c.
# Thus c < k and c >= ceil(k/3).
#
# Writing d = k-c, the equation gives c^2 d = a^3+b^3.
# Since c >= k/3 and a <= b:
#   d <= 9(a^3+b^3)/k^2 <= 18/(a^4 b).
# But d is a positive integer, so a^4 b <= 18. With a <= b,
# this forces a=1 and 1 <= b <= 18. The enumeration below is finite
# and checks the original equation exactly.

sorted_solutions = []
tested = 0

for a in range(1, 19):
    for b in range(a, 19):
        if a**4 * b > 18:
            continue
        k = a * a * b * b
        lower = max(b, (k + 2) // 3)
        for c in range(lower, k):
            tested += 1
            if a**3 + b**3 + c**3 == (a * b * c)**2:
                sorted_solutions.append((a, b, c))

solutions = sorted({
    p
    for triple in sorted_solutions
    for p in itertools.permutations(triple)
})

final_answer = "All triples are " + json.dumps(solutions, separators=(",", ":")) + "."

result = {
    "final_answer": final_answer,
    "evidence": {
        "finite_bound": "After sorting a<=b<=c, a^4*b<=18, hence a=1 and 1<=b<=18.",
        "enumeration": {
            "candidate_c_values_tested": tested,
            "sorted_solutions": [list(t) for t in sorted_solutions],
            "all_permutations": [list(t) for t in solutions],
            "original_equation_verified": all(
                a**3 + b**3 + c**3 == (a * b * c)**2
                for a, b, c in solutions
            ),
        },
    },
}
print(json.dumps(result, separators=(",", ":")))
