# Each piece is represented by its bounds and an interior sample point.
pieces = [
    (None, Fraction(20), Fraction(19)),
    (Fraction(20), Fraction(22), Fraction(21)),
    (Fraction(22), Fraction(24), Fraction(23)),
    (Fraction(24), None, Fraction(25)),
]

