terms = [(1, -24), (1, -20), (-2, 44)]
solutions = []
evidence = []

for lo, hi, sample in pieces:
    a = Fraction(0)
    b = Fraction(0)
    for coeff, constant in terms:
        sign = 1 if coeff * sample + constant > 0 else -1
        a += sign * coeff
        b += sign * constant

    domain = (
        f"({ '-inf' if lo is None else lo }, "
        f"{ 'inf' if hi is None else hi })"
    )

    if a == 0:
        if b == 0:
            solutions.append((lo, hi))
            zero = "whole piece"
        else:
            zero = "none"
    else:
        root = -b / a
        if (lo is None or root >= lo) and (hi is None or root <= hi):
            solutions.append((root, root))
            zero = str(root)
        else:
            zero = "none"

    evidence.append({
        "piece": domain,
        "affine": f"{a}*x+{b}",
