from fractions import Fraction
from math import isqrt

def pow2(e):
    return Fraction(1 << e, 1) if e >= 0 else Fraction(1, 1 << (-e))

def rounded_sqrt(n):
    r = isqrt(n)
    # Exact test for sqrt(n) >= r + 1/2; ties cannot occur for integer n.
    return r + (4 * n >= 4 * r * r + 4 * r + 1)

def group_direct(k):
    lo = k * k - k + 1
    hi = k * k + k
    assert all(rounded_sqrt(n) == k for n in range(lo, hi + 1))
    return sum(
        (pow2(k) + pow2(-k)) * pow2(-n)
        for n in range(lo, hi + 1)
    )

def group_closed(k):
    # Geometric sum over n = k^2-k+1, ..., k^2+k.
    return pow2(1 - (k - 1) ** 2) - pow2(1 - (k + 1) ** 2)

for k in range(1, 21):
    assert group_direct(k) == group_closed(k)

# The groups cover every positive integer: group k ends at k^2+k,
# and group k+1 starts at k^2+k+1.
for k in range(1, 20):
    assert k * k + k + 1 == (k + 1) ** 2 - (k + 1) + 1

# The grouped terms telescope separately by parity:
# sum(k=1..K) = 3 - 2^(1-K^2) - 2^(1-(K+1)^2).
for K in range(1, 21):
    direct = sum((group_direct(k) for k in range(1, K + 1)), Fraction(0))
    telescoped = 3 - pow2(1 - K * K) - pow2(1 - (K + 1) ** 2)
    assert direct == telescoped

print("Partial sum through group 10:",
      sum((group_direct(k) for k in range(1, 11)), Fraction(0)))
print("Exact infinite-series value: 3")
print("Submitted answer: 5")
print("CHECK PASS: grouping and finite telescoping identities verified.")
print("CHECK FAIL: submitted answer is not the series value.")
