        g = math.gcd(a, b)
        return apply("[]", a, b) if g == 1 else g
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    raise ValueError(f"Unknown operator: {op}")

def evaluate(text):
    tokens = TOKEN_RE.findall(text)
    if "".join(tokens).replace(" ", "") != re.sub(r"\s+", "", text):
        raise ValueError("Could not tokenize expression")
    pos = 0
    operators = {"[]", "><", ";", "~", "#", "!", "+", "-", "*"}

    def expression(min_bp=0):
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        token = tokens[pos]
        pos += 1

        if token == "-":
            left = -expression(30)
        elif token == "(":
            left = expression()
            if pos >= len(tokens) or tokens[pos] != ")":
                raise ValueError("Missing closing parenthesis")
            pos += 1
        elif token.isdigit():
            left = int(token)
        elif token in WORDS:
            left = WORDS[token]
        else:
            raise ValueError(f"Unexpected token: {token}")

        while pos < len(tokens) and tokens[pos] in operators and 10 >= min_bp:
            op = tokens[pos]
            pos += 1
            right = expression(11)
            left = apply(op, left, right)
        return left

    result = expression()
    if pos != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos]}")
    return result

values = {name: evaluate(expr) for name, expr in EXPRESSIONS.items()}
answer = values["A"] + values["B"] - values["C"]
print(json.dumps({
    "final_answer": str(answer),
    "evidence": values,
}, separators=(",", ":")))
