import json
import math


def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def apply(a, b, op):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "!":
        return a + b if a - b > 0 else a * b
    if op == ":":
        return a * b if a - b > 0 else (-a) * (-b)
    if op == "~":
        if abs(a - b) < 2:
            return apply(b, a, ":") - b
        return apply(a, b, ":") - a
    if op == "#":
        if b < 2:
            return apply(apply(a, a, "~"), b, "!")
        return apply(apply(b, b, "~"), a, "!")
    if op == "<>":
        g = math.gcd(a, b)
        return apply(a, b, "#") if g == 1 else g
    if op == "][":
        return min(a, b) if is_prime(a) or is_prime(b) else max(a, b)
    raise ValueError("Unknown operator: " + op)


def chain(a, b, *ops):
    for op in ops:
        a = apply(a, b, op)
    return a


# A
a0 = chain(-10, 10, "-", "!")
a1 = chain(-6, 10, "#", "<>")
a_base = a0 - a1
a_mid = chain(
    apply(-1, -2, "#"),
    chain(7, -7, "!"),
    "][", "]["
)
a_left = chain(a_base, a_mid, "#", "*", "-")

a_right_base = chain(
    chain(-2, -10, "!"),
    chain(-8, -7, "~", "!", "+"),
    "-", "*"
)
a_right_rhs = chain(
    chain(9, -2, "*", "!", "!"),
    chain(8, -2, "<>"),
    "*", "+", "<>"
)
a_right = chain(a_right_base, a_right_rhs, "#", "*")
A = apply(a_left, a_right, "][")

# B
b_left_base = chain(-6, -3, "][", "+") - apply(-1, -7, "#")
b_left_rhs = apply(
    chain(-10, -6, "!"),
    apply(-6, 1, ":"),
    "<>"
)
b_left = chain(b_left_base, b_left_rhs, "-", "*", "<>")

b_q = chain(
    apply(1, 7, "<>"),
    chain(8, 8, "][", "-", "*"),
    "-", "#"
)
b_s = apply(
    chain(-8, 1, "+", ":", ":"),
    chain(6, 1, "#", "+"),
    ":"
)
b_right = apply(b_q, b_s, "][")
B = apply(b_left, b_right, "*")

# C
c_left = chain(
    apply(2, -3, "!"),
    chain(-4, -5, "+", ":", "~"),
    "#", "-"
)
c_rhs = apply(
    chain(4, 4, "-", "<>"),
    apply(5, 2, "#"),
    "#"
)
c_first = chain(c_left, c_rhs, ":", "*", "#")

c_second_base = chain(
    apply(8, -10, ":"),
    chain(2, -1, "*", "*", "<>"),
    "][", ":", "!"
)
c_second_rhs = chain(-6, -4, "+", "!") - apply(4, 8, "*")
c_second = apply(c_second_base, c_second_rhs, "][")
C = apply(c_first, c_second, "<>")

result = A + B - C
print(json.dumps({
    "final_answer": str(result),
    "evidence": {"A": str(A), "B": str(B), "C": str(C)}
