import itertools
import json
from collections import deque

# Buildings are indexed in the same order as their classes and initial owners.
names = ("Garza", "Yates", "Zimmer", "Flores",
         "Lynch", "King", "Meyer", "Ortiz")
classes = (1, 3, 3, 1, 2, 2, 2, 2)
initial = (0, 0, 0, 1, 1, 2, 2, 2)  # RealProp, Southco, Trustcorp
weights = {1: 4, 2: 2, 3: 1}

targets = {
    "A": (0, {"Lynch", "Meyer", "Ortiz"}),
    "B": (1, {"Garza", "Meyer"}),
    "C": (1, {"King", "Meyer", "Ortiz"}),
    "D": (2, {"Flores", "Yates"}),
    "E": (2, {"Garza", "Lynch"}),
}

def holdings(state, owner, cls):
    return [i for i, (own, c) in enumerate(zip(state, classes))
            if own == owner and c == cls]

def exchange(state, owner_a, bundle_a, owner_b, bundle_b):
    result = list(state)
    for i in bundle_a:
        result[i] = owner_b
    for i in bundle_b:
        result[i] = owner_a
    return tuple(result)

def successors(state):
    for a in range(3):
        for b in range(a + 1, 3):
            # One building for one building of the same class.
            for cls in (1, 2, 3):
                for x in holdings(state, a, cls):
                    for y in holdings(state, b, cls):
                        yield exchange(state, a, (x,), b, (y,))

            # One class-1 building for two class-2 buildings.
            for x in holdings(state, a, 1):
                for pair in itertools.combinations(holdings(state, b, 2), 2):
                    yield exchange(state, a, (x,), b, pair)
            for x in holdings(state, b, 1):
                for pair in itertools.combinations(holdings(state, a, 2), 2):
                    yield exchange(state, b, (x,), a, pair)

            # One class-2 building for two class-3 buildings.
            for x in holdings(state, a, 2):
                for pair in itertools.combinations(holdings(state, b, 3), 2):
                    yield exchange(state, a, (x,), b, pair)
            for x in holdings(state, b, 2):
                for pair in itertools.combinations(holdings(state, a, 3), 2):
                    yield exchange(state, b, (x,), a, pair)

reachable = {initial}
queue = deque([initial])
while queue:
    state = queue.popleft()
    for nxt in successors(state):
        if nxt not in reachable:
            reachable.add(nxt)
            queue.append(nxt)

def matches(state, owner, wanted):
    actual = {names[i] for i, own in enumerate(state) if own == owner}
    return actual == wanted

possible = {
    label: any(matches(state, owner, wanted)
               for state in reachable)
    for label, (owner, wanted) in targets.items()
}
impossible = [label for label in targets if not possible[label]]

answer = impossible[0] if len(impossible) == 1 else "UNSUPPORTED"
target_values = {
    label: sum(weights[classes[names.index(name)]] for name in wanted)
    for label, (_, wanted) in targets.items()
}

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "reachable_states": len(reachable),
        "possible": possible,
        "target_values": target_values,
        "each_company_initial_value": 6
    }
}))
