    if option == "B":
        return p["V"] < p["W"] < p["Z"]
    if option == "C":
        return p["V"] < p["X"] and p["W"] < p["X"]
    if option == "D":
        return abs(p["X"] - p["U"]) == 1
    if option == "E":
        return p["X"] in (5, 6)
    raise ValueError(option)

alternatives = {
    option: {
        order for order in orders
        if common_rules(order) and option_rule(option, order)
    }
    for option in "ABCDE"
}

equivalent = [option for option, result in alternatives.items()
              if result == baseline]

answer = equivalent[0] if len(equivalent) == 1 else "UNSUPPORTED"
evidence = {
