from collections import deque
from itertools import combinations

# A state gives the owner (0=RealProp, 1=Southco, 2=Trustcorp) of each building.
names = [
    "Garza Tower", "Yates House", "Zimmer House", "Flores Tower",
    "Lynch Building", "King Building", "Meyer Building", "Ortiz Building",
]
classes = [1, 3, 3, 1, 2, 2, 2, 2]
initial = (0, 0, 0, 1, 1, 2, 2, 2)
company_names = ["RealProp", "Southco", "Trustcorp"]
value = {1: 4, 2: 2, 3: 1}

# Exhaustively enumerate states reachable by the three allowed kinds of trade.
seen = {initial}
queue = deque([initial])

while queue:
    state = queue.popleft()
    holdings = {
        company: [b for b, owner in enumerate(state) if owner == company]
        for company in range(3)
    }
    successors = []

    # One building for one building of the same class.
    for a in range(3):
        for b in range(a + 1, 3):
            for x in holdings[a]:
                for y in holdings[b]:
                    if classes[x] == classes[y]:
                        nxt = list(state)
                        nxt[x], nxt[y] = b, a
                        successors.append(tuple(nxt))

    # One class-1 building for two class-2 buildings;
    # one class-2 building for two class-3 buildings.
    for a in range(3):
        for b in range(3):
            if a == b:
                continue
            for single_class, pair_class in ((1, 2), (2, 3)):
                singles = [x for x in holdings[a] if classes[x] == single_class]
                pairs = [x for x in holdings[b] if classes[x] == pair_class]
                for single in singles:
                    for pair in combinations(pairs, 2):
                        nxt = list(state)
                        nxt[single] = b
                        for x in pair:
                            nxt[x] = a
                        successors.append(tuple(nxt))

    for nxt in successors:
        if nxt not in seen:
            seen.add(nxt)
            queue.append(nxt)

# Each statement specifies the company's exact set of buildings.
options = {
    "A": (0, {"Lynch Building", "Meyer Building", "Ortiz Building"}),
    "B": (1, {"Garza Tower", "Meyer Building"}),
    "C": (1, {"King Building", "Meyer Building", "Ortiz Building"}),
    "D": (2, {"Flores Tower", "Yates House"}),
    "E": (2, {"Garza Tower", "Lynch Building"}),
}

reachable = {}
witnesses = {}
for letter, (company, target_names) in options.items():
    target = {names.index(name) for name in target_names}
    witness = next(
        (
            state for state in seen
            if {i for i, owner in enumerate(state) if owner == company} == target
        ),
        None,
    )
    reachable[letter] = witness is not None
    witnesses[letter] = witness

print(f"Exhaustive reachable states: {len(seen)} of {3 ** len(names)} possible assignments")
for letter in options:
    print(f"Option {letter}: {'reachable' if reachable[letter] else 'unreachable'}")
    if witnesses[letter] is not None:
        company = options[letter][0]
        owned = [
            names[i] for i, owner in enumerate(witnesses[letter])
            if owner == company
        ]
        print(f"  Witness holdings for {company_names[company]}: {owned}")

# The trade values are 4, 2, 1 for classes 1, 2, 3, respectively.
initial_trust_value = sum(
    value[classes[i]] for i, owner in enumerate(initial) if owner == 2
)
d_target_value = value[1] + value[3]
print(f"Trustcorp initial value: {initial_trust_value}; option D target value: {d_target_value}")

cannot_be_true = [letter for letter in options if not reachable[letter]]
print(f"Cannot be true: {cannot_be_true}")
submitted = "A"
if cannot_be_true == [submitted]:
    print("CHECK PASS")
else:
    print(f"CHECK FAIL: submitted {submitted} is reachable; exhaustive search identifies {cannot_be_true}")
