import json

def is_prime(m):
    if m < 2:
        return False
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1
    return True

def prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

n = 33146799
factors = prime_factors(n)

product = 1
for p in factors:
    product *= p

counts = {}
for p in factors:
    counts[p] = counts.get(p, 0) + 1

all_prime = all(is_prime(p) for p in counts)
product_ok = (product == n)

