def prepare(text):
    def capital_value(match):
        country, claimed_capital = match.group(1).lower(), match.group(2).lower()
        return "True" if capitals.get(country) == claimed_capital else "False"

    text = re.sub(
        r"The capital of ([A-Za-z]+) is ([A-Za-z]+)\.",
        capital_value,
        text,
        flags=re.IGNORECASE,
    )
    text = text.replace("is less than or equal to", "<=")
    text = text.replace("is greater than or equal to", ">=")
    text = text.replace("is greater than", ">")
    text = text.replace("is less than", "<")
    return text

TOKEN_RE = re.compile(r"\d+|[A-Za-z_]+|<=|>=|==|!=|[()+\-*/,<>]")

class Parser:
    def __init__(self, text):
        self.tokens = TOKEN_RE.findall(prepare(text))
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def take(self, expected=None):
        token = self.peek()
        if token is None or (expected is not None and token != expected):
            raise ValueError(f"Expected {expected!r}, got {token!r}")
        self.i += 1
        return token

    def parse(self):
        value = self.parse_or()
        if self.peek() is not None:
            raise ValueError(f"Unexpected token {self.peek()!r}")
        return value

    def parse_or(self):
        value = self.parse_and()
        while self.peek() == "or":
            self.take()
            right = self.parse_and()
            value = bool(value) or bool(right)
        return value

    def parse_and(self):
        value = self.parse_not()
        while self.peek() == "and":
            self.take()
            right = self.parse_not()
            value = bool(value) and bool(right)
        return value

    def parse_not(self):
        if self.peek() == "not":
            self.take()
            return not bool(self.parse_not())
        return self.parse_compare()

    def parse_compare(self):
        left = self.parse_sum()
        op = self.peek()
        if op in (">", "<", ">=", "<=", "==", "!="):
            self.take()
            right = self.parse_sum()
            return {
                ">": lambda: left > right,
                "<": lambda: left < right,
                ">=": lambda: left >= right,
                "<=": lambda: left <= right,
                "==": lambda: left == right,
                "!=": lambda: left != right,
            }[op]()
        return left

    def parse_sum(self):
        value = self.parse_product()
        while self.peek() in ("+", "-"):
            op = self.take()
            right = self.parse_product()
            value = value + right if op == "+" else value - right
        return value

    def parse_product(self):
        value = self.parse_unary()
        while self.peek() in ("*", "/"):
            op = self.take()
            right = self.parse_unary()
            value = value * right if op == "*" else value / right
        return value

    def parse_unary(self):
        if self.peek() == "-":
            self.take()
            return -self.parse_unary()
        if self.peek() == "+":
            self.take()
            return self.parse_unary()
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()
        if token == "(":
            self.take()
            value = self.parse_or()
            self.take(")")
            return value
        if token in ("max", "min"):
            function = self.take()
            self.take("(")
            args = [self.parse_or()]
            while self.peek() == ",":
                self.take()
                args.append(self.parse_or())
            self.take(")")
            return (max if function == "max" else min)(args)
        if token == "True":
            self.take()
            return True
        if token == "False":
            self.take()
            return False
        if token is not None and token.isdigit():
            return Fraction(int(self.take()))
        raise ValueError(f"Unexpected token {token!r}")

