from itertools import combinations

# Treat “A or B” as meaning the grade chooses at least one of those events.
RUN = "long-distance running"
SPRINT = "sprint"
HIGH = "high jump"
LONG = "long jump"
SHOT = "shot put"

events = (RUN, SPRINT, HIGH, LONG, SHOT)
options = {
    "A": {SPRINT, SHOT},
    "B": {SPRINT, LONG},
    "C": {SHOT, HIGH},
    "D": {RUN, HIGH},
}

def compatible(chosen):
    if RUN in chosen and chosen & {SPRINT, HIGH, LONG}:
        return False
    if LONG in chosen and chosen & {RUN, SHOT}:
        return False
    return True

# Exhaustively enumerate positive grade sizes totaling 12. Requiring all
# four sizes to differ follows the strongest natural reading of “varies.”
def grade_sizes():
    for a in range(1, 10):
        for b in range(1, 10):
            for c in range(1, 10):
                d = 12 - a - b - c
                sizes = (a, b, c, d)
                if d >= 1 and len(set(sizes)) == 4:
                    yield sizes

# Legal selections of one or two events for a grade that chooses running.
running_selections = []
for k in (1, 2):
    for group in combinations(events, k):
        chosen = set(group)
        if RUN in chosen and compatible(chosen):
            running_selections.append(chosen)

print("Legal one/two-event selections containing long-distance running:")
for chosen in running_selections:
    print(" ", sorted(chosen))

# Find exact witnesses satisfying a non-smallest grade and enough players
# to enter each selected event. A witness gives the four grade sizes and
# the selected grade's event choices.
witnesses = {}
for sizes in grade_sizes():
    smallest = min(sizes)
    for i, count in enumerate(sizes):
        if count <= smallest:
            continue
        for chosen in running_selections:
            if count < len(chosen):
                continue
            for label, pair in options.items():
                if chosen & pair:
                    witnesses.setdefault(label, (sizes, i + 1, chosen))

print("\nOption feasibility (OR means at least one listed event is chosen):")
for label in "ABCD":
    if label in witnesses:
        sizes, grade, chosen = witnesses[label]
        print(f"{label}: POSSIBLE; grade {grade}, sizes={sizes}, "
              f"chosen={sorted(chosen)}")
