        facts.add(atom)
        return True
    return False

# Forward-chain the rules until no more conclusions can be added.
changed = True
while changed:
    changed = False

    # Rule 1: education -> ostrich does not invest in shark-owned company.
    if ("works_in", "ostrich", "education") in facts:
        changed |= add(("not_invests_in_company_owned_by", "ostrich", "shark"))

