                ("not_invests_in_company_owned_by", "ostrich", "shark")
            )

    # Rule 7: shark younger than 18 months -> acquires swallow photo.
    for predicate, animal, age_months in tuple(facts):
        if predicate == "age_months" and animal == "shark" and age_months < 18:
            changed |= add(("acquires_photo_of", "shark", "swallow"))

    # Rule 8: paying the badger -> smiles at the basenji.
    for predicate, animal, recipient in tuple(facts):
