import itertools
import json

categories = ("opinion", "size", "age", "shape",
              "color", "origin", "material", "purpose")

# Category sequences observed in the given correct sentences.
observations = [
    ("purpose", "origin"),                 # exercise Egyptian shoe
    ("opinion", "size"),                   # lovely huge bicycle
    ("opinion", "color", "purpose"),       # wonderful gray driving bicycle
    ("material", "color"),                # paper black shirt
    ("size", "material", "origin"),        # midsize iron Mexican jar
    ("age", "shape"),                      # archaic circular speaker
]

# Every earlier category in an observed sentence precedes every later one.
constraints = {
    (a, b)
    for sequence in observations
    for i, a in enumerate(sequence)
    for b in sequence[i + 1:]
}

options = {
    "A": ("opinion", "size", "material", "color", "purpose", "origin", "age"),
    "B": ("shape", "material", "color", "purpose", "origin", "size", "opinion"),
    "C": ("shape", "age", "material", "color", "purpose", "origin", "size"),
    "D": ("age", "material", "color", "purpose", "origin", "size", "opinion"),
    "E": ("opinion", "size", "material", "color", "purpose", "origin", "age", "shape"),
    "F": ("opinion", "size", "material", "color", "purpose", "origin"),
    "G": ("opinion", "size", "material", "color", "purpose", "origin", "shape"),
    "H": ("age", "shape", "material", "color", "purpose", "origin"),
    "I": ("age", "shape", "material", "color", "purpose", "origin", "size", "opinion"),
    "J": ("size", "material", "color", "purpose", "origin", "age", "shape"),
}

valid_orders = []
answer_counts = {option: 0 for option in options}
witnesses = {}

for order in itertools.permutations(categories):
    rank = {category: i for i, category in enumerate(order)}
    if not all(rank[a] < rank[b] for a, b in constraints):
        continue

    valid_orders.append(order)
    answer = "".join(
        option for option, sequence in options.items()
        if all(rank[a] < rank[b] for a, b in zip(sequence, sequence[1:]))
    )
    answer_counts = {
        option: count + (option in answer)
        for option, count in answer_counts.items()
    }
    witnesses.setdefault(answer, order)

all_answers = list(witnesses)
if len(all_answers) == 1:
    final_answer = all_answers[0]
    witness_evidence = {}
else:
    final_answer = "UNSUPPORTED"
    witness_evidence = {
        "distinct_answers": len(all_answers),
        "witnesses": [
            {"answer": answer, "order": list(witnesses[answer])}
            for answer in all_answers[:2]
        ],
    }

total = len(valid_orders)
status = {
    option: ("always" if count == total else
             "never" if count == 0 else "varies")
    for option, count in answer_counts.items()
}

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "observed_precedence_constraints": sorted(constraints),
        "consistent_total_orders": total,
        "option_status_across_orders": status,
        **witness_evidence,
    },
}, separators=(",", ":")))
