from itertools import combinations

def subsets(n):
    base = range(n)
    for r in range(n + 1):
        for c in combinations(base, r):
            yield frozenset(c)

def search(n, prem, concl):
    # Exhaustive over all pairs of subsets of a universe of size n.
    for P in subsets(n):
        for Q in subsets(n):
            if prem(P, Q, n) and not concl(P, Q, n):
                return (sorted(P), sorted(Q))
    return None

# Each option: (premise, conclusion) over two monadic predicates P, Q on range(n).
# Premise and conclusion are written from the option's own wording.
options = {
    # Orig: Some good things are not cheap / Not all cheap things are good
    # good=P, cheap=Q
    "Original": (
        lambda P, Q, n: any(x in P and x not in Q for x in range(n)),
        lambda P, Q, n: any(x in Q and x not in P for x in range(n)),
    ),
    # A: Some Hunan people don't like pepper / Some pepper lovers aren't from Hunan
    # Hunan=P, pepper=Q
    "A": (
        lambda P, Q, n: any(x in P and x not in Q for x in range(n)),
        lambda P, Q, n: any(x in Q and x not in P for x in range(n)),
    ),
    # B: Some people aren't selfish / Not all people are selfish
    # people=P, selfish=Q
    "B": (
        lambda P, Q, n: any(x in P and x not in Q for x in range(n)),
        lambda P, Q, n: any(x in P and x not in Q for x in range(n)),
    ),
    # C: Good motive not necessarily good effect / Good results not necessarily from good motive
    # good motive=P, good effect=Q
    "C": (
        lambda P, Q, n: any(x in P and x not in Q for x in range(n)),
        lambda P, Q, n: any(x in Q and x not in P for x in range(n)),
    ),
    # D: Some southerners aren't Cantonese / Not all Cantonese are southerners
    # southerner=P, Cantonese=Q
    "D": (
        lambda P, Q, n: any(x in P and x not in Q for x in range(n)),
        lambda P, Q, n: any(x in Q and x not in P for x in range(n)),
    ),
}

invalid = []
for name, (prem, concl) in options.items():
    counter = None
    for n in range(1, 4):
        counter = search(n, prem, concl)
        if counter is not None:
            print(f"{name}: INVALID, counterexample at n={n}: P={counter[0]}, Q={counter[1]}")
            break
    else:
        print(f"{name}: no counterexample for n<=3 (exhaustive up to size 3)")
    if counter is not None:
        invalid.append(name)

print("Invalid options:", invalid)

# Submitted answer C: check that its inference is invalid.
if "C" in invalid:
    print("Submitted C is an invalid inference: CHECK PASS")
else:
    print("Submitted C is not shown invalid: CHECK FAIL")

# Uniqueness: the question asks for a single option.
if len(invalid) == 1:
    print("Unique invalid option is", invalid[0], ": CHECK PASS")
else:
    print("Invalid options are", invalid, "so C is not the unique invalid option: CHECK UNKNOWN")
