from fractions import Fraction as F
import json

def vec(xs):
    return tuple(F(x) for x in xs)

def dot(a, b):
    return sum((x*y for x, y in zip(a, b)), F(0))

def cross(a, b):
    return (a[1]*b[2] - a[2]*b[1],
            a[2]*b[0] - a[0]*b[2],
            a[0]*b[1] - a[1]*b[0])

def nonzero(a):
    return any(x != 0 for x in a)

def parallel(a, b):
    if not nonzero(a) or not nonzero(b):
        return False
    return all(a[i]*b[j] - a[j]*b[i] == 0
               for i in range(len(a)) for j in range(i+1, len(a)))

def plane(normal, offset):
    return (vec(normal), F(offset))

def line(point, direction):
    return (vec(point), vec(direction))

def planes_distinct(p, q):
    # Plane equations are represented by (normal, -offset).
    return not parallel(p[0] + (-p[1],), q[0] + (-q[1],))

def lines_distinct(L, M):
    p, v = L
    q, w = M
    return not (parallel(v, w) and not nonzero(cross(tuple(q[i]-p[i] for i in range(3)), v)))

def planes_perp(p, q):
    return dot(p[0], q[0]) == 0

def line_perp_plane(L, p):
    return parallel(L[1], p[0])

def lines_perp(L, M):
    return dot(L[1], M[1]) == 0

def plane_intersection_is(p, q, L):
    direction = cross(p[0], q[0])
    return (nonzero(direction)
            and parallel(direction, L[1])
            and dot(p[0], L[0]) == p[1]
            and dot(q[0], L[0]) == q[1])

# Explicit exact counterexamples, with all named planes and lines distinct.
examples = {
    "A": {
        "alpha": plane((0, 0, 1), 0), "beta": plane((0, 1, 0), 0),
        "gamma": plane((1, 0, 0), 2),
        "l": line((0, 0, 0), (1, 0, 0)),
        "m": line((0, 1, 0), (0, 0, 1)),
        "n": line((0, 0, 1), (0, 1, 0)),
    },
    "B": {
        "alpha": plane((1, 0, 0), 0), "beta": plane((1, 0, 0), 1),
        "gamma": plane((0, 0, 1), 0),
        "m": line((0, 0, 0), (0, 1, 0)),
        "n": line((0, 0, 1), (1, 0, 0)),
        "l": line((1, 0, 0), (0, 0, 1)),
    },
    "C": {
        "alpha": plane((1, 0, 0), 0), "beta": plane((0, 1, 0), 0),
        "gamma": plane((0, 0, 1), 0),
        "m": line((0, 1, 1), (1, 0, 0)),
        "n": line((0, 0, 0), (0, 1, 0)),
        "l": line((1, 0, 0), (0, 0, 1)),
    },
}

def all_distinct(x):
    ps = [x[k] for k in ("alpha", "beta", "gamma")]
    ls = [x[k] for k in ("m", "n", "l")]
    return (all(planes_distinct(ps[i], ps[j]) for i in range(3) for j in range(i+1, 3))
            and all(lines_distinct(ls[i], ls[j]) for i in range(3) for j in range(i+1, 3)))

def condition_holds(letter, x):
    a, b, g = x["alpha"], x["beta"], x["gamma"]
    m = x["m"]
    if letter == "A":
        return (planes_perp(a, b) and plane_intersection_is(a, b, x["l"])
                and lines_perp(m, x["l"]))
    if letter == "B":
        return (plane_intersection_is(a, g, m)
                and planes_perp(a, g) and planes_perp(b, g))
    if letter == "C":
        return planes_perp(a, g) and planes_perp(b, g) and line_perp_plane(m, a)
    raise ValueError(letter)

counterexamples = []
for option, x in examples.items():
    assert all_distinct(x)
    assert condition_holds(option, x)
    assert not line_perp_plane(x["m"], x["beta"])
    counterexamples.append(option)

# D follows from the exact parallel-vector formula
# u x (a x u) = (u·u)a - (u·a)u:
# since u != 0, u || a follows from u || a's cross-product condition.
# In D, the direction u of n is parallel to both plane normals a,b.
# The direction v of m is parallel to a. Thus a,b,v are all parallel,
# so v is parallel to b, exactly m perpendicular beta.
d_algebraic_implication = (
    "u!=0; u×a=0 and u×b=0 imply a,b parallel to u; "
    "v×a=0 then implies v×b=0"
)
assert d_algebraic_implication

sufficient = [x for x in ("A", "B", "C", "D") if x not in counterexamples]
assert sufficient == ["D"]

print(json.dumps({
    "final_answer": sufficient[0],
    "evidence": {
        "counterexamples": counterexamples,
        "each_counterexample_satisfies_its_conditions": True,
        "each_counterexample_fails_m_perp_beta": True,
        "D_exact_vector_implication": d_algebraic_implication
    }
}, separators=(",", ":")))
