import itertools
import json

# Category-order constraints read from the multi-adjective examples:
# "little silly", "archaic indigo", "whittling Bangladeshi",
# "wool rectangular", "paper gray typing", and
# "triangular ancient Chinese".
categories = (
    "MATERIAL", "SHAPE", "AGE", "COLOR",
    "PURPOSE", "ORIGIN", "SIZE", "OPINION"
)
edges = (
    ("SIZE", "OPINION"),
    ("AGE", "COLOR"),
    ("PURPOSE", "ORIGIN"),
    ("MATERIAL", "SHAPE"),
    ("MATERIAL", "COLOR"),
    ("COLOR", "PURPOSE"),
    ("SHAPE", "AGE"),
    ("AGE", "ORIGIN"),
)

options = {
    "A": ("SIZE", "OPINION", "AGE", "COLOR", "PURPOSE", "ORIGIN", "SHAPE", "MATERIAL"),
    "B": ("SHAPE", "AGE", "COLOR", "PURPOSE", "ORIGIN", "OPINION", "SIZE"),
    "C": ("AGE", "COLOR", "PURPOSE", "ORIGIN", "OPINION", "SIZE"),
    "D": ("MATERIAL", "SHAPE", "AGE", "COLOR", "PURPOSE", "ORIGIN"),
    "E": ("OPINION", "AGE", "COLOR", "PURPOSE", "ORIGIN", "SHAPE", "MATERIAL"),
    "F": ("SIZE", "OPINION", "AGE", "COLOR", "PURPOSE", "ORIGIN"),
    "G": ("MATERIAL", "SHAPE", "AGE", "COLOR", "PURPOSE", "ORIGIN", "OPINION", "SIZE"),
    "H": ("SIZE", "AGE", "COLOR", "PURPOSE", "ORIGIN", "SHAPE", "MATERIAL"),
    "I": ("OPINION", "SIZE", "AGE", "COLOR", "PURPOSE", "ORIGIN", "SHAPE"),
    "J": ("MATERIAL", "SHAPE", "AGE", "COLOR", "PURPOSE", "ORIGIN", "SIZE"),
}

def respects(order, sequence):
    rank = {category: i for i, category in enumerate(order)}
    return all(rank[a] < rank[b] for a, b in zip(sequence, sequence[1:]))

linear_extensions = [
    order for order in itertools.permutations(categories)
    if all(order.index(a) < order.index(b) for a, b in edges)
]
valid_counts = {
    key: sum(respects(order, sequence) for order in linear_extensions)
    for key, sequence in options.items()
}
ambiguous = [
    key for key, count in valid_counts.items()
    if 0 < count < len(linear_extensions)
]

# The examples constrain only a partial order. Since at least one option
# is correct in some compatible total orders but not in others, the exact
# requested answer cannot be settled from the givens alone.
final_answer = "UNSUPPORTED" if ambiguous else "".join(
    key for key, count in valid_counts.items()
    if count == len(linear_extensions)
)

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "compatible_total_orders": len(linear_extensions),
        "valid_order_counts": valid_counts,
        "ambiguous_options": ambiguous
    }
}))
