    """cands: list of (rule, value). Apply stated preferences to conflicting values."""
    if len({v for _, v in cands}) == 1:
        return cands[0][1]
    present = {r for r, _ in cands}

    def dominated(r):
        return any((p, r) in PREFS for p in present)

