nums = [float(x) for x in re.findall(r"[-+]?\d+(?:\.\d*)?(?:[eE][-+]?\d+)?", path)]
points = [(nums[i], nums[i + 1]) for i in range(0, len(nums), 2)]
segments = [(points[i], points[i + 1]) for i in range(0, len(points), 2)]

EPS = 1e-7
KEY_EPS = 1e-5

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def close(a, b, tol=KEY_EPS):
    return math.hypot(a[0] - b[0], a[1] - b[1]) <= tol

def on_segment(p, a, b):
    ab, ap = sub(b, a), sub(p, a)
    scale = max(1.0, math.hypot(*ab))
    return (abs(cross(ab, ap)) <= 1e-6 * scale
            and dot(ap, sub(p, b)) <= 1e-6 * scale)

# Polygon corners must occur at an SVG endpoint or at a segment intersection.
vertices = list(points)
for i, (a, b) in enumerate(segments):
    r = sub(b, a)
    for c, d in segments[i + 1:]:
        s = sub(d, c)
        denom = cross(r, s)
        if abs(denom) < EPS:
            continue
        t = cross(sub(c, a), s) / denom
        u = cross(sub(c, a), r) / denom
        if -EPS <= t <= 1 + EPS and -EPS <= u <= 1 + EPS:
            vertices.append((a[0] + t * r[0], a[1] + t * r[1]))

# Deduplicate the arrangement vertices.
unique = []
for p in vertices:
    if not any(close(p, q) for q in unique):
        unique.append(p)
vertices = unique

def boundary_drawn(p, q):
    """Whether the entire straight edge p--q is covered by SVG segments."""
    v = sub(q, p)
    length2 = dot(v, v)
    if length2 < EPS:
        return False
    intervals = []
    for a, b in segments:
        if abs(cross(v, sub(a, p))) > 1e-6 * max(1.0, math.sqrt(length2)):
            continue
        if abs(cross(v, sub(b, p))) > 1e-6 * max(1.0, math.sqrt(length2)):
            continue
        ta = dot(sub(a, p), v) / length2
        tb = dot(sub(b, p), v) / length2
        lo, hi = sorted((ta, tb))
        lo, hi = max(0.0, lo), min(1.0, hi)
        if hi >= lo - EPS:
            intervals.append((lo, hi))
    intervals.sort()
    reached = 0.0
    for lo, hi in intervals:
        if lo > reached + 1e-6:
            return False
        reached = max(reached, hi)
        if reached >= 1.0 - 1e-6:
            return True
    return False

# Cache all fully drawn straight edges between arrangement vertices.
edges = set()
for i, p in enumerate(vertices):
    for j in range(i + 1, len(vertices)):
        if boundary_drawn(p, vertices[j]):
            edges.add((i, j))
            edges.add((j, i))

neighbors = [[] for _ in vertices]
for i, j in edges:
    neighbors[i].append(j)

rectangles = []
nonrect_parallelograms = []

# Exhaust all possible adjacent-corner pairs. For a parallelogram with
# adjacent sides AB and AD, the fourth corner must be C = B + D - A.
for ai, a in enumerate(vertices):
    for bi in neighbors[ai]:
        b = vertices[bi]
        ab = sub(b, a)
        for di in neighbors[ai]:
            if di == bi:
                continue
            d = vertices[di]
            ad = sub(d, a)
            if abs(cross(ab, ad)) < 1e-5:
                continue
            c = (b[0] + d[0] - a[0], b[1] + d[1] - a[1])
            ci = next((k for k, p in enumerate(vertices) if close(p, c)), None)
            if ci is None or (bi, ci) not in edges or (di, ci) not in edges:
                continue
            # A, B, C, D are the boundary corners in order.
            if abs(dot(ab, ad)) <= 1e-5 * max(1.0, math.hypot(*ab) * math.hypot(*ad)):
                candidate = tuple((round(vertices[k][0], 4), round(vertices[k][1], 4))
                                  for k in (ai, bi, ci, di))
                if candidate not in rectangles:
                    rectangles.append(candidate)
            else:
                candidate = tuple((round(vertices[k][0], 4), round(vertices[k][1], 4))
                                  for k in (ai, bi, ci, di))
                if candidate not in nonrect_parallelograms:
                    nonrect_parallelograms.append(candidate)

print("Arrangement vertices:", len(vertices))
print("Rectangle boundary candidates:", len(rectangles))
print("Non-rectangular parallelogram boundary candidates:",
      len(nonrect_parallelograms))
if rectangles:
