# Check a plausible alternative: 10 rows and 8 columns, with each move
# going to a white square in the row above, at the same or an adjacent
# column. Enumerate exactly, for every starting column and either color
# of P. In a checkerboard, a vertical neighbor has the opposite color;
# a diagonal neighbor has the same color.
def count_paths_10_by_8(start_col, start_white):
    width = 8
    # State: (column, is_white); value: number of paths reaching it.
    dp = {(start_col, start_white): 1}
    for _ in range(9):
        nxt = {}
        for (col, is_white), count in dp.items():
            for new_col in range(max(0, col - 1), min(width, col + 2)):
                diagonal = abs(new_col - col) == 1
                new_white = is_white if diagonal else not is_white
                if new_white:
                    key = (new_col, new_white)
                    nxt[key] = nxt.get(key, 0) + count
        dp = nxt
    return sum(count for (col, _), count in dp.items() if col == start_col)

