for _, sequence in evidence_sentences:
    for i, earlier in enumerate(sequence):
        for later in sequence[i + 1:]:
            edges.add((earlier, later))

def adjective_class(word):
    word = word.lower()
    if word in {"old-fashioned", "ancient", "archaic", "old", "new",
                "brand-new"}:
        return "AGE"
    if word in {"steel", "plastic", "fiberglass", "wool", "cloth",
                "leather", "glass", "paper", "rubber", "wood"}:
