    if word in {"walking", "drinking", "snorkeling", "whittling",
                "exercise", "eating"}:
        return "ACTIVITY"
    if word in {"indigo", "aqua", "violet", "blue", "magenta", "cyan",
                "yellow"}:
        return "COLOR"
    if word in {"pyramidal", "spherical", "rectangular", "circular"}:
        return "SHAPE"
    if word in {"medium-size", "midsize", "little", "small", "large",
                "enormous"}:
        return "SIZE"
    raise ValueError(f"Unclassified option adjective: {word}")

