from fractions import Fraction as Fr
import json
import math

# Polynomials in monomials (c, s, z) = (cos t, sin t, z), a = 1.
# Flux scales as a^3 by substitution z = a*u, dS = a*dt*dz, F.n = a*(1 + u(s - c)).

def padd(p, q):
    r = dict(p)
    for k, v in q.items():
        r[k] = r.get(k, Fr(0)) + v
    return {k: v for k, v in r.items() if v != 0}

def pscale(p, s):
    return {k: v * s for k, v in p.items() if v * s != 0}

def pmul(p, q):
    r = {}
    for (a1, b1, c1), v1 in p.items():
        for (a2, b2, c2), v2 in q.items():
            key = (a1 + a2, b1 + b2, c1 + c2)
            r[key] = r.get(key, Fr(0)) + v1 * v2
    return {k: v for k, v in r.items() if v != 0}

# Wallis-type integrals over [0, pi/2], returned as (rational r, flag k) meaning r*(pi/2)^k.
def B(n):
    # integral_0^{pi/2} sin^n
    if n == 0:
        return (Fr(1), 1)
    if n == 1:
        return (Fr(1), 0)
    r, k = B(n - 2)
    return (r * Fr(n - 1, n), k)

def J(p, q):
    # integral_0^{pi/2} cos^p sin^q
    if p == 0:
        return B(q)
    if p == 1:
        return (Fr(1, q + 1), 0)
    r, k = J(p - 2, q)
    return (r * Fr(p - 1, p + q), k)

def symint(p, q):
    # integral_{-pi/2}^{pi/2} cos^p sin^q dt
    if q % 2 == 1:
        return (Fr(0), 0)  # odd in t over symmetric interval
    r, k = J(p, q)
    return (2 * r, k)

# Domain: cylinder x^2+y^2=1 (a=1), outward normal n = (x, y, 0).
# Region z >= 0 and z <= x forces cos t >= 0, i.e. t in [-pi/2, pi/2], and 0 <= z <= cos t.
X = {(1, 0, 0): Fr(1)}   # x = cos t
Y = {(0, 1, 0): Fr(1)}   # y = sin t
Z = {(0, 0, 1): Fr(1)}   # z

# F = (x-z) i + (y+z) j + (x-y) k ; F.n with n = (x, y, 0)
Fx = padd(X, pscale(Z, -1))
Fy = padd(Y, Z)
Fdotn = padd(pmul(Fx, X), pmul(Fy, Y))

# Integrate in z from 0 to upper limit x = c: z^k -> c^(k+1)/(k+1)
after_z = {}
for (i, j, k), v in Fdotn.items():
    key = (i + k + 1, j, 0)
    after_z[key] = after_z.get(key, Fr(0)) + v / (k + 1)

# Integrate over t
R = Fr(0)
P = Fr(0)  # coefficient of (pi/2)
for (p, q, _), v in after_z.items():
    r, k = symint(p, q)
    if k == 0:
        R += v * r
    else:
        P += v * r

exact_coef = R + P * Fr(1, 1) * (math.pi / 2) if P == 0 else None
if P == 0:
    coef_str = str(R)
    final = f"{R}*a^3"
    exact_float = float(R)
else:
    coef_str = f"{R}+({P})*pi/2"
    final = f"({R}+{P}*pi/2)*a^3"
    exact_float = float(R) + float(P) * math.pi / 2

# Independent numeric check directly from the definitions (midpoint rule, a = 1)
def F(x, y, z):
    return (x - z, y + z, x - y)

N, M = 400, 200
numeric = 0.0
for i in range(N):
    t = -math.pi / 2 + (i + 0.5) * math.pi / N
    x, y = math.cos(t), math.sin(t)
    top = x
    if top <= 0:
        continue
    dz = top / M
    dt = math.pi / N
    for j in range(M):
        z = (j + 0.5) * dz
        Fx_, Fy_, _ = F(x, y, z)
        numeric += (Fx_ * x + Fy_ * y) * dz * dt

ok = abs(numeric - exact_float) < 1e-3
result = {
    "final_answer": final if ok else "UNSUPPORTED",
    "evidence": {
        "coefficient_of_a3": coef_str,
        "exact_float": round(exact_float, 10),
        "numeric_check": round(numeric, 6),
        "agrees": ok,
        "domain": "t in [-pi/2, pi/2], 0 <= z <= a*cos(t)",
        "normal": "outward radial (cos t, sin t, 0)",
        "dS": "a dt dz",
    },
}
print(json.dumps(result))
