import math
import re

WORDS = {
    "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
}

A_EXPR = "((((4 + 4) ! (7 # eight)) ~ ((five ! four) * (-7 : -6))) + (((eight >< three) : (-3 - three)) # ((-10 + -8) ! (-4 # -10))))"
B_EXPR = "((((((((((((((((-4 # -6) ~ -7) - two) >< -3) ~ three) + ten) >< 4) + -6) + 9) * two) * -9) ! -1) : 9) # six) ~ 6) ! 6)"
C_EXPR = "(((((((((((((((((((((two - -5) : -3) ~ 7) + -1) >< 10) : -4) * -7) # four) # -9) + 9) * -8) >< -9) ! one) # -6) ~ -8) # -2) >< -3) + 3) ! eight) - -2) - nine)"
CLAIMED_B = 6

TOKEN_RE = re.compile(r"\s*(><|[()+\-*:~!#]|\d+|[A-Za-z]+)")


def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def colon(a, b):
    # a : b = (a+a)*b if b<2 else (b+b)*a
    return (a + a) * b if b < 2 else (b + b) * a


def cross(a, b):
    # a >< b = a*b if a:b > 0 else (-a)*(-b)
    return a * b if colon(a, b) > 0 else (-a) * (-b)


def tilde(a, b):
    # a ~ b = a-b if gcd==1 else gcd
    g = math.gcd(a, b)
    return a - b if g == 1 else g


def bang(a, b):
    # a ! b = min if either is prime else max
    return min(a, b) if (is_prime(a) or is_prime(b)) else max(a, b)


def hash_op(a, b):
    # a # b = a-b if a~b > 0 else a:b
    return a - b if tilde(a, b) > 0 else colon(a, b)


BINOPS = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    ":": colon,
    "><": cross,
    "~": tilde,
    "!": bang,
    "#": hash_op,
}


def tokenize(s):
    tokens = []
    pos = 0
    while pos < len(s):
        m = TOKEN_RE.match(s, pos)
        if not m:
            if s[pos:].strip() == "":
                break
            raise ValueError("bad input near position %d" % pos)
        tokens.append(m.group(1))
        pos = m.end()
    return tokens


class Parser:
    def __init__(self, tokens):
        self.t = tokens
        self.i = 0
        self.max_ops = 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def operand(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        if tok == "(":
            self.take()
            v = self.seq()
            if self.take() != ")":
                raise ValueError("expected ')'")
            return v
        if tok == "-":
            self.take()
            return -self.operand()
        if tok.isdigit():
            self.take()
            return int(tok)
        if tok.lower() in WORDS:
            self.take()
            return WORDS[tok.lower()]
        raise ValueError("bad token %r" % tok)

    def seq(self):
        v = self.operand()
        n = 0
        while self.peek() is not None and self.peek() in BINOPS:
            op = self.take()
            n += 1
            r = self.operand()
            v = BINOPS[op](v, r)
        self.max_ops = max(self.max_ops, n)
        return v


def evaluate(s):
    tokens = tokenize(s)
    p = Parser(tokens)
    value = p.operand()
    if p.i != len(tokens):
        raise ValueError("trailing tokens after expression")
    if p.max_ops > 1:
        raise ValueError("a parenthesized group has several operators; precedence is ambiguous")
    return value


def main():
    results = {}
    for name, expr in (("A", A_EXPR), ("B", B_EXPR), ("C", C_EXPR)):
        try:
            results[name] = evaluate(expr)
        except ValueError as e:
            print("UNSUPPORTED: cannot evaluate %s (%s)" % (name, e))
            return

    A, B, C = results["A"], results["B"], results["C"]
    print("A =", A)
    print("B =", B)
    print("C =", C)
    print("A + B - C =", A + B - C)
    print("Claimed B =", CLAIMED_B, "| computed B =", B)
    if B == CLAIMED_B:
        print("CHECK PASS")
    else:
        print("CHECK FAIL")


main()
