import re
from fractions import Fraction

# Real-world capitals used to decide the truth of the embedded capital statements.
REAL_CAPITALS = {
    "India": "New Delhi",
    "Armenia": "Yerevan",
    "Turkey": "Ankara",
    "Afghanistan": "Kabul",
    "Jordan": "Amman",
    "Nigeria": "Abuja",
    "UAE": "Abu Dhabi",
    "Canada": "Ottawa",
}


def _norm(country):
    c = country.strip()
    if c.startswith("the "):
        c = c[4:]
    return c


def CAP(country, claim):
    return REAL_CAPITALS.get(_norm(country)) == claim.strip()


def translate(expr):
    # Capital statements -> CAP(country, claim)
    s = re.sub(
        r"\(The capital of (.+?) is (.+?)\.\)",
        lambda m: 'CAP("%s","%s")' % (m.group(1), m.group(2)),
        expr,
    )
    # Natural-language comparators -> Python operators
    s = s.replace("is less than or equal to", "<=")
    s = s.replace("is greater than", ">")
    # Integers -> exact rationals so division is exact
