```python
import re
import json
from fractions import Fraction as F

# Truth values for the embedded factual statements (standard world-knowledge facts).
FACTS = {
    ("Colombia", "Bogota"): True,
    ("Turkey", "Ankara"): True,
    ("Canada", "Ottawa"): True,
    ("Jordan", "Beirut"): False,      # Jordan's capital is Amman
    ("Belarus", "Minsk"): True,
    ("Afghanistan", "Kabul"): True,
    ("Afghanistan", "Kandahar"): False,
    ("Nepal", "Pokhara"): False,      # Nepal's capital is Kathmandu
    ("India", "New Delhi"): True,
    ("Denmark", "Copenhagen"): True,
    ("Iran", "Isfahan"): False,       # Iran's capital is Tehran
}

def translate(s):
    # Replace factual statements with their truth values.
    def fact(m):
        key = (m.group(1), m.group(2))
        if key not in FACTS:
            raise KeyError(key)
        return str(FACTS[key])
    s = re.sub(r'The capital of (\w+) is ([\w ]+?)\.', fact, s)
    # Replace comparison phrases (longest first).
    s = s.replace('is less than or equal to', '<=')
    s = s.replace('is less than', '<')
    s = s.replace('is greater than', '>')
    # Wrap integers in exact Fractions so division is exact.
    s = re.sub(r'-?\d+', lambda m: 'F(' + m.group(0) + ')', s)
    return s

def evaluate(expr):
    env = {"F": F, "max": max, "min": min, "__builtins__": {}}
