import string


def normalize(cells):
    m = min(cells)
    return tuple(sorted((r - m[0], c - m[1]) for r, c in cells))


# The three-cell L-tromino is a 2x2 square with one cell removed: 4 orientations.
BASE = [(0, 0), (0, 1), (1, 0), (1, 1)]
SHAPES = set()
for skip in range(4):
    SHAPES.add(normalize([BASE[i] for i in range(4) if i != skip]))
SHAPES = sorted(SHAPES)


def solve(n):
    """Exhaustive backtracking: cover the first empty cell in row-major order.
    Any tromino covering that cell must have it as its row-major minimum,
    so trying every normalized L-shape anchored there is a complete search."""
    grid = [[None] * n for _ in range(n)]
    pieces = []

    def first_empty():
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    return (r, c)
        return None

    def rec():
        pos = first_empty()
        if pos is None:
            return True
        r0, c0 = pos
        for sh in SHAPES:
            cells = [(r0 + dr, c0 + dc) for dr, dc in sh]
            if all(0 <= r < n and 0 <= c < n and grid[r][c] is None for r, c in cells):
                pid = len(pieces)
                pieces.append(cells)
                for r, c in cells:
                    grid[r][c] = pid
                if rec():
                    return True
                for r, c in cells:
                    grid[r][c] = None
                pieces.pop()
        return False

    ok = rec()
    return ok, grid, pieces


def verify_tiling(n, grid, pieces):
    """Check that the pieces are L-trominoes, disjoint, and cover the n x n square."""
    seen = set()
    for cells in pieces:
        if len(cells) != 3 or len(set(cells)) != 3:
            return False
        if normalize(cells) not in SHAPES:
            return False
        for r, c in cells:
            if not (0 <= r < n and 0 <= c < n):
                return False
            if (r, c) in seen:
                return False
            seen.add((r, c))
    return len(seen) == n * n and len(pieces) * 3 == n * n


# 1) Exact tileability for small squares (complete search, so exact for these sizes).
results = {}
for n in range(1, 7):
    ok, grid, pieces = solve(n)
    results[n] = (ok, grid, pieces)
    print(f"n={n}: area={n*n}, area%3={(n*n)%3}, L-tromino tiling exists={ok}")

# 2) Check the submitted answer "No" against the constructed counterexample.
#    Side 6 is the smallest counterexample found by the search above
#    (n=3 is also tested exhaustively; n=1,2,4,5 fail the area divisibility test).
ok6, grid6, pieces6 = results[6]
if ok6:
    valid = verify_tiling(6, grid6, pieces6)
    print(f"6x6 pieces used: {len(pieces6)} (expected 12)")
    print(f"6x6 tiling verified (disjoint L-trominoes covering all 36 cells): {valid}")
    if valid:
        symbols = string.ascii_uppercase
        for r in range(6):
            print(" ".join(symbols[grid6[r][c]] for c in range(6)))
        print("CHECK PASS: a square tiling by L-trominoes exists (6x6 verified).")
        print("CHECK FAIL: submitted answer 'No' is refuted; the answer 'Yes' is correct for side 6.")
    else:
        print("CHECK UNKNOWN: found a candidate 6x6 tiling but verification failed.")
else:
    print("CHECK UNKNOWN: no 6x6 tiling found by search.")

# 3) Note on sizes: the n=3 search is exhaustive and finds no tiling, so the
#    answer depends on the side length, not on the shape alone.
print(f"n=3 tileable (exhaustive): {results[3][0]}")
print("Assumption: the figure shows the standard three-cell L-tromino (2x2 square minus one cell).")
