        CAT[w] = cat

add("opinion", "lovely silly nice terrible awful obnoxious repulsive wonderful good mysterious ridiculous")
add("size", "huge enormous large big tiny small little medium-size midsize normal-size massive")
add("shape", "circular spherical square triangular rectangular prismlike pyramidal")
add("age", "archaic ancient old old-fashioned new brand-new")
add("color", "yellow gray cyan red violet pink indigo blue crimson green white black maroon magenta aqua brown")
add("origin", "pakistani ethiopian filipino russian vietnamese chinese german mexican nigerian indian egyptian iranian congolese bangladeshi indonesian japanese brazilian thai american turkish")
add("material", "steel glass wood rubber leather cardboard wool paper plastic fiberglass cloth iron")
add("verb", "driving typing whittling hiking walking smoking eating snorkeling exercise drinking")

# Directly attested precedences (X before Y) from the givens:
# opinion<origin (e.g. 14, 27, 35), origin<verb (143), verb<color (6, 21, 28),
# age<material (20, 30, 41), material<opinion (50), shape<size (26, 37, 46)
ATTESTED = [("opinion", "origin"), ("origin", "verb"), ("verb", "color"),
            ("age", "material"), ("material", "opinion"), ("shape", "size")]

REL = set(ATTESTED)
cats = sorted({c for pair in ATTESTED for c in pair} | set(CAT.values()))
changed = True
while changed:
    changed = False
    for a in cats:
        for b in cats:
            for c in cats:
                if (a, b) in REL and (b, c) in REL and (a, c) not in REL:
                    REL.add((a, c))
                    changed = True

OPTIONS = {
    "A": "obnoxious nigerian walking indigo pyramidal medium-size car",
    "B": "little prismlike awful iranian smoking white bed",
