    result = "valid"
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            x, y = seq[i], seq[j]
            if x == y:
                continue
            if (y, x) in REL:
                result = "invalid"
            elif (x, y) not in REL and result != "invalid":
                result = "unknown"
    status[key] = {"categories": seq, "status": result}
    if result == "valid":
